import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executor;
class AsyncTotals {
    static CompletableFuture<Integer> doubled(int value, Executor executor) {
        return CompletableFuture.supplyAsync(() -> {
            if (value < 0) throw new IllegalArgumentException("negative value");
            return value;
        }, executor).thenApply(n -> n * 2);
    }
}

import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
class WorkerTotals {
    static int sum() throws Exception {
        try (var executor = Executors.newFixedThreadPool(2)) {
            var first = executor.submit(() -> 1 + 2 + 3);
            var second = executor.submit(() -> 4 + 5 + 6);
            return first.get(2, TimeUnit.SECONDS) + second.get(2, TimeUnit.SECONDS);
        }
    }
}

