import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest
@AutoConfigureMockMvc
class OrderApiTest {
    @Autowired MockMvc mvc;
    @Test void getsSample() throws Exception {
        mvc.perform(get("/orders/sample")).andExpect(status().isOk())
            .andExpect(jsonPath("$.name").value("tea")).andExpect(jsonPath("$.quantity").value(2));
    }
    @Test void acceptsOrder() throws Exception {
        mvc.perform(post("/orders").contentType("application/json")
            .content("{\"name\":\"tea\",\"quantity\":3}"))
            .andExpect(status().isCreated()).andExpect(jsonPath("$.quantity").value(3));
    }
    @Test void rejectsBadInput() throws Exception {
        for (String json : new String[]{"{", "{\"name\":\"\",\"quantity\":1}", "{\"name\":\"tea\",\"quantity\":0}"}) {
            mvc.perform(post("/orders").contentType("application/json").content(json))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.error").value("invalid order"));
        }
    }
    @Test void reportsUnavailableName() throws Exception {
        mvc.perform(post("/orders").contentType("application/json")
            .content("{\"name\":\"reserved\",\"quantity\":1}"))
            .andExpect(status().isConflict()).andExpect(jsonPath("$.error").value("unavailable name"));
    }
}
